import React, { useState, useMemo } from 'react';
import { ArrowDown, ChevronDown, Settings, Edit2, X, Sparkles, Fuel, Ban, Skull, Clock, Target, Check, AlertTriangle, Layers, Info, BarChart3, Activity, Zap } from 'lucide-react';
import { AreaChart, Area, XAxis, YAxis, Tooltip, ResponsiveContainer, ReferenceLine } from 'recharts';
import { formatMoney, formatToken, formatTokenAmount, EducationalTooltip, ETH_ICON, USDC_ICON } from './Shared';

interface LimitPanelProps {
  amount: string;
  onAmountChange: (val: string) => void;
  balance: number;
}

const LimitPanel: React.FC<LimitPanelProps> = ({ amount, onAmountChange, balance }) => {
  const [limitPrice, setLimitPrice] = useState('3208.93');
  const [expiry, setExpiry] = useState('24h');
  const [postOnly, setPostOnly] = useState(false);
  const [isDetailsOpen, setIsDetailsOpen] = useState(false); // Progressive Disclosure State

  const ETH_PRICE = 3208.93;
  const numericPay = parseFloat(amount) || 0;
  const isInsufficientBalance = numericPay > balance;

  // --- REFINED MATH ENGINE ---
  const simulation = useMemo(() => {
    const pay = numericPay;
    const limitP = parseFloat(limitPrice) || ETH_PRICE;
    const grossValue = pay * limitP;

    // 1. Maker vs Taker Logic
    // Sell Order: If Limit Price < Market Price, it executes immediately against bids (Taker)
    const distanceToMarket = ((limitP - ETH_PRICE) / ETH_PRICE) * 100;
    const isMarketable = distanceToMarket <= 0; 

    // 2. Fee Tier Logic (Institutional)
    const MAKER_BPS = 2;   // 0.02%
    const TAKER_BPS = 10;  // 0.10%

    // If Post Only is checked, we assume Maker fee (or rejection)
    // Otherwise, dynamic based on marketability
    const activeFeeBps = (postOnly || !isMarketable) ? MAKER_BPS : TAKER_BPS;
    const feeTierLabel = (postOnly || !isMarketable) ? 'MAKER' : 'TAKER';

    const platformFee = grossValue * (activeFeeBps / 10000);
    const networkFee = 9.75; // Estimated L2 Gas

    // 3. Net Calculation
    const totalFees = platformFee + networkFee;
    const netLimitReceive = Math.max(0, grossValue - totalFees);

    // 4. Effective Price (The true price per unit after costs)
    const effectivePrice = pay > 0 ? netLimitReceive / pay : 0;

    // 5. Post-Only Conflict Detection
    // If user enforces Post-Only but price is marketable, engine rejects.
    const postOnlyWarning = postOnly && isMarketable;

    // 6. Probability Engine
    let expiryHours = 24;
    if(expiry === '10m') expiryHours = 0.16;
    else if(expiry === '1h') expiryHours = 1;
    else if(expiry === '3d') expiryHours = 72;
    else if(expiry === '7d') expiryHours = 168;
    else if(expiry === 'GTC') expiryHours = 720; // 30 days approx

    // Volatility based probability (Mock Gaussian)
    const HOURLY_VOLATILITY = 0.035 / Math.sqrt(24); 
    const stdDevsNeeded = (Math.abs(distanceToMarket)/100) / (HOURLY_VOLATILITY * Math.sqrt(expiryHours));
    let rawProb = 100 * Math.exp(-0.5 * Math.pow(stdDevsNeeded, 2));
    if (isMarketable) rawProb = 100; // Immediate execution
    const execProbability = Math.round(Math.min(99, Math.max(1, rawProb)));

    // 7. Time Horizon Estimation
    let timeHorizon = 'Instant';
    if (!isMarketable) {
        const expectedHours = (Math.abs(distanceToMarket)) * 12; // 1% move takes ~12h
        if(expectedHours < 1) timeHorizon = '< 1 Hour';
        else if(expectedHours < 24) timeHorizon = `~${Math.ceil(expectedHours)} Hours`;
        else timeHorizon = `~${Math.ceil(expectedHours/24)} Days`;
    }

    // 8. Opportunity Cost (Yield Drag)
    // If funds are locked in an order, they aren't earning 4.2% APY in Aave
    const dailyYieldLoss = grossValue * 0.042 * (expiryHours/8760);

    return {
        grossValue,
        netLimitReceive,
        effectivePrice,
        distanceToMarket,
        isMarketable,
        postOnlyWarning,
        platformFee,
        networkFee,
        feeTierLabel,
        activeFeeBps,
        execProbability,
        probColor: execProbability > 75 ? '#10b981' : execProbability > 40 ? '#f59e0b' : '#f43f5e',
        timeHorizon,
        dailyYieldLoss,
        structureLabel: limitP < 3180 ? 'BELOW SUPPORT' : limitP > 3280 ? 'BREAKOUT' : 'IN RANGE',
    };
  }, [numericPay, limitPrice, expiry, postOnly]);

  const depthData = useMemo(() => {
      const data = [];
      const startPrice = ETH_PRICE * 0.95;
      const endPrice = ETH_PRICE * 1.05;
      const steps = 40;
      const stepSize = (endPrice - startPrice) / steps;
      for(let i=0; i<=steps; i++) {
          const p = startPrice + i*stepSize;
          let bidVol=0, askVol=0;
          if(p < ETH_PRICE) bidVol = 5000 + Math.abs(ETH_PRICE-p)*2000;
          if(p > ETH_PRICE) askVol = 5000 + Math.abs(p-ETH_PRICE)*2500;
          data.push({ price: p, bidVol, askVol });
      }
      return data;
  }, [limitPrice]);

  const handlePercentageClick = (pct: number) => {
    const maxSafe = Math.max(0, balance - 0.01);
    const val = (maxSafe * pct) / 100;
    onAmountChange(val.toFixed(4));
  };

  const isPercentageActive = (pct: number) => {
    if (balance <= 0) return false;
    const maxSafe = Math.max(0, balance - 0.01);
    const targetVal = (maxSafe * pct) / 100;
    return amount === targetVal.toFixed(4);
  };

  const adjustLimitPrice = (pct: number) => {
      const newPrice = pct === 0 ? ETH_PRICE : ETH_PRICE * (1 + pct / 100);
      setLimitPrice(newPrice.toFixed(2));
  };

  const ACTIVE_LIMIT_ORDERS = [
      { id: 'ord_1', time: '14:32:05', pair: 'ETH/USDC', side: 'Sell', size: '350.00 ETH', filledPct: 12, price: 3320.00 },
      { id: 'ord_2', time: '14:30:22', pair: 'SOL/USDC', side: 'Buy', size: '1,200 SOL', filledPct: 68, price: 138.50 },
  ];

  return (
    <>
      <section className="lg:col-span-4 flex flex-col h-full gap-5">
         {/* Main Input Panel */}
         <div className="glass-panel p-2">
            <div className="bg-[#0a0a0a] rounded-[2.2rem] p-6 border border-white/5 space-y-2">

                {/* 1. PAY INPUT BLOCK */}
                <div className="bg-[#050505] rounded-3xl p-5 border border-white/5 focus-within:border-emerald-500/30 transition-colors group relative">
                    <div className="flex justify-between items-start mb-4">
                        <label className="text-[9px] font-black text-zinc-500 uppercase tracking-[0.2em] group-focus-within:text-emerald-500 transition-colors">You Sell</label>
                        <div className="text-[9px] font-bold text-zinc-500 bg-zinc-900 px-2 py-1 rounded-lg border border-white/5 flex items-center gap-2">
                            <span>Bal: <span className="font-mono text-zinc-300">{formatToken(balance)}</span></span>
                            <button onClick={() => handlePercentageClick(100)} className="text-emerald-500 hover:text-emerald-400 font-black text-[8px] uppercase">Max</button>
                        </div>
                    </div>

                    <div className="flex items-center gap-4">
                        <input 
                            type="text" 
                            value={amount}
                            onChange={(e) => onAmountChange(e.target.value)}
                            className="w-full bg-transparent text-4xl lg:text-5xl font-mono font-medium tracking-tighter text-white placeholder:text-zinc-800 focus:outline-none" 
                            placeholder="0.00" 
                        />
                        <button className="flex items-center gap-2 bg-zinc-900 border border-white/10 pl-2 pr-3 py-2 rounded-xl hover:bg-zinc-800 transition-all shrink-0 active:scale-95">
                            <div className="w-6 h-6 rounded-full bg-black border border-white/10 flex items-center justify-center p-0.5">
                                <img src={ETH_ICON} className="w-full h-full object-contain" alt="ETH" />
                            </div>
                            <span className="font-bold text-white text-sm">ETH</span>
                            <ChevronDown size={12} className="text-zinc-500" />
                        </button>
                    </div>

                    {/* Footer: USD Value & Percentages */}
                    <div className="flex justify-between items-center mt-3">
                        <div className="text-xs font-mono font-bold text-zinc-600">
                            ≈ {amount ? formatMoney(numericPay * ETH_PRICE) : '$0.00'}
                        </div>
                        <div className="flex gap-1">
                            {[25, 50, 75, 100].map(pct => (
                                <button 
                                    key={pct} 
                                    onClick={() => handlePercentageClick(pct)} 
                                    className={`text-[9px] font-bold px-2 py-1 rounded border transition-all ${
                                        isPercentageActive(pct)
                                        ? 'bg-zinc-700 text-white border-white/20 shadow-sm' 
                                        : 'text-zinc-600 hover:text-zinc-300 bg-zinc-900/50 border-white/5'
                                    }`}
                                >
                                    {pct}%
                                </button>
                            ))}
                        </div>
                    </div>
                </div>

                {/* CONNECTOR */}
                <div className="relative h-4 w-full flex items-center justify-center z-10 -my-3">
                    <div className="p-1.5 bg-[#0a0a0a] rounded-full border border-white/10 shadow-xl">
                        <div className="bg-zinc-900 p-1.5 rounded-full text-zinc-500">
                            <ArrowDown size={14} strokeWidth={3} />
                        </div>
                    </div>
                </div>

                {/* 2. LIMIT SETTINGS BLOCK */}
                <div className={`bg-[#050505] rounded-3xl p-5 border transition-colors ${simulation.postOnlyWarning ? 'border-rose-500/30' : 'border-white/5 focus-within:border-emerald-500/30'}`}>
                    <div className="flex justify-between items-center mb-4">
                        <label className="text-[9px] font-black text-zinc-500 uppercase tracking-[0.2em]">Target Price</label>
                        <div className="flex gap-1">
                            <button onClick={() => adjustLimitPrice(0)} className="text-[8px] font-bold bg-zinc-900 text-zinc-500 border border-white/5 px-2 py-1 rounded hover:text-white transition-colors">MARKET</button>
                            <button onClick={() => adjustLimitPrice(5)} className="text-[8px] font-bold bg-zinc-900 text-zinc-500 border border-white/5 px-2 py-1 rounded hover:text-white transition-colors">+5%</button>
                        </div>
                    </div>

                    <div className="flex items-center gap-4 mb-6">
                        <span className="text-2xl font-mono text-zinc-500">$</span>
                        <input 
