                            <YAxis hide />
                            <Tooltip cursor={{ stroke: '#ffffff', strokeWidth: 1, strokeDasharray: '3 3' }} contentStyle={{ backgroundColor: '#09090b', borderColor: '#333', borderRadius: '12px', fontSize: '10px' }} />
                            <Area type="stepAfter" dataKey="bidVol" stroke="#10b981" fill="url(#bidGrad)" strokeWidth={2} />
                            <Area type="stepAfter" dataKey="askVol" stroke="#ef4444" fill="url(#askGrad)" strokeWidth={2} />
                            <ReferenceLine x={ETH_PRICE} stroke="#71717a" strokeDasharray="3 3" label={{ position: 'top', value: 'MKT', fill: '#71717a', fontSize: 9, fontWeight: 700 }} />
                            <ReferenceLine x={parseFloat(limitPrice)} stroke="#3b82f6" strokeWidth={2} label={{ position: 'top', value: 'YOU', fill: '#3b82f6', fontSize: 9, fontWeight: 800 }} />
                        </AreaChart>
                    </ResponsiveContainer>
                </div>
             </div>

             {/* Active Orders List */}
             <div className="bg-[#0a0a0a] border border-white/5 rounded-2xl p-5 overflow-hidden">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="text-[10px] font-black text-zinc-500 uppercase tracking-[0.2em]">Active Orders</h3>
                    <span className="text-[9px] font-bold text-emerald-500 flex items-center gap-2 bg-emerald-500/10 px-2 py-0.5 rounded border border-emerald-500/20">
                        <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse"></span> 2 LIVE
                    </span>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full text-left">
                        <thead>
                            <tr className="text-[9px] font-black text-zinc-500 uppercase tracking-widest border-b border-white/5">
                                <th className="pb-3 pl-2">Time</th><th className="pb-3">Pair</th><th className="pb-3 text-right">Size</th><th className="pb-3 text-right">Filled</th><th className="pb-3 text-right pr-2">Action</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-white/5">
                            {ACTIVE_LIMIT_ORDERS.map(order => (
                                <tr key={order.id} className="group hover:bg-white/[0.02] transition-colors">
                                    <td className="py-3 pl-2 text-xs font-mono font-bold text-zinc-500">{order.time}</td>
                                    <td className="py-3 text-xs font-bold text-white">{order.pair}</td>
                                    <td className="py-3 text-right text-xs font-mono font-bold text-zinc-300">{order.size}</td>
                                    <td className="py-3 text-right text-xs font-mono font-bold text-emerald-500">{order.filledPct}%</td>
                                    <td className="py-3 text-right pr-2">
                                        <button className="p-1.5 hover:bg-rose-500/10 text-zinc-500 hover:text-rose-500 rounded transition-colors"><X size={12}/></button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
             </div>
          </div>
      </section>
    </>
  );
};

export default LimitPanel;

