import React from 'react';
import { ArrowDown, ChevronDown, Check, User, Fuel, Lock } from 'lucide-react';
import { TokenSelectorModal, formatMoney, formatToken, formatTokenAmount, getTokenLogo } from './Shared';

interface SwapFormProps {
    amount: string;
    onAmountChange: (val: string) => void;
    balance: number;
    logic: any;
}

export const SwapForm: React.FC<SwapFormProps> = ({ amount, onAmountChange, balance, logic }) => {
    const { 
        payToken, setPayToken, receiveToken, setReceiveToken, 
        selectingSide, setSelectingSide,
        recipientMode, setRecipientMode, recipientAddress, setRecipientAddress,
        gasSpeed, setGasSpeed,
        isReviewing, setIsReviewing, reviewTimer,
        isSimulating, hasAmount, simulation, ETH_PRICE, numericPay, isInsufficientBalance
    } = logic;

    const isPercentageActive = (pct: number) => {
        if (balance <= 0) return false;
        const maxSafe = Math.max(0, balance - 0.01);
        const targetVal = (maxSafe * pct) / 100;
        return amount === targetVal.toFixed(4);
    };

    const handlePercentageClick = (pct: number) => {
        const maxSafe = Math.max(0, balance - 0.01);
        const val = (maxSafe * pct) / 100;
        onAmountChange(val.toFixed(4));
    };

    const handleTokenSelect = (token: any) => {
        if (selectingSide === 'pay') setPayToken(token);
        if (selectingSide === 'receive') setReceiveToken(token);
        setSelectingSide(null);
    };

    const handleFlip = () => {
        const tempToken = payToken;
        setPayToken(receiveToken);
        setReceiveToken(tempToken);
    };

    return (
        <>
            <TokenSelectorModal isOpen={!!selectingSide} onClose={() => setSelectingSide(null)} onSelect={handleTokenSelect} />

