import React, { useState, useMemo, useEffect } from 'react';
import { ArrowDown, ChevronDown, Settings, Eye, Info, Sparkles, StopCircle, LayoutGrid, Clock, Zap, TrendingUp, CheckCircle2, Bot, Layers, BarChart3, Activity, Cpu } from 'lucide-react';
import { ComposedChart, Bar, Cell, XAxis, YAxis, Tooltip, ResponsiveContainer, Line } from 'recharts';
import { formatMoney, formatToken, formatTokenAmount, EducationalTooltip, ETH_ICON, USDC_ICON } from '../Shared/Shared';

interface AlgoPanelProps {
  amount: string;
  onAmountChange: (val: string) => void;
  balance: number;
}

const AlgoPanel: React.FC<AlgoPanelProps> = ({ amount, onAmountChange, balance }) => {
  const [algoStrategy, setAlgoStrategy] = useState<'TWAP' | 'VWAP' | 'ICEBERG'>('TWAP');
  const [algoDuration, setAlgoDuration] = useState(4); // Hours
  const [algoRandomize, setAlgoRandomize] = useState(false);
  const [participationRate, setParticipationRate] = useState(10);
  const [icebergVisibleAmount, setIcebergVisibleAmount] = useState('');

  const [isAlgoRunning, setIsAlgoRunning] = useState(false);
  const [executionProgress, setExecutionProgress] = useState(0);
  const [isDetailsOpen, setIsDetailsOpen] = useState(false); // Progressive Disclosure

  const numericPay = parseFloat(amount) || 0;
  const isInsufficientBalance = numericPay > balance;
  const ETH_PRICE = 3208.93;

  // --- PERCENTAGE HELPERS (Unified Style) ---
  const handlePercentageClick = (pct: number) => {
    const maxSafe = Math.max(0, balance - 0.01);
    const val = (maxSafe * pct) / 100;
    onAmountChange(val.toFixed(4));
  };

  const isPercentageActive = (pct: number) => {
    if (balance <= 0) return false;
    const maxSafe = Math.max(0, balance - 0.01);
    const targetVal = (maxSafe * pct) / 100;
    return amount === targetVal.toFixed(4);
  };

  // --- SIMULATION RUNNER ---
  useEffect(() => {
    let interval: ReturnType<typeof setInterval>;
    if (isAlgoRunning && executionProgress < 100) {
      interval = setInterval(() => {
        setExecutionProgress(prev => Math.min(prev + 0.2, 100)); // Simulation tick
      }, 100);
    }
    return () => clearInterval(interval);
  }, [isAlgoRunning, executionProgress]);

  // --- MATH ENGINE ---
  const simulation = useMemo(() => {
    const pay = numericPay;
    const grossValue = pay * ETH_PRICE;

    // 1. Constants for Simulation
    const LIQUIDITY_DEPTH_USD = 15_000_000; // Depth required to move price 2%
    const VOLATILITY_FACTOR = 0.8; // Power law exponent (0.5 - 1.0 usually)
    const GAS_PER_TX_USD = 9.75;
    const PLATFORM_BPS = 5; // 0.05%

    // 2. Strategy Logic & Tranche Calculation
    let numTranches = 1;
    let strategyLabel = 'Time Weighted';
    let alphaSource = 'Variance Reduction';
    let avgIntervalMins = 0;
    let distributionProfile: number[] = [];

    // Calculate Tranches
    const totalDurationMins = algoDuration * 60;

    if (algoStrategy === 'ICEBERG') {
        strategyLabel = 'Hidden Liquidity';
        alphaSource = 'Signaling Risk';
        // Clip size is manually set or defaults to 10%
        const visibleAmt = parseFloat(icebergVisibleAmount) || (pay * 0.1);
        numTranches = Math.ceil(pay / (visibleAmt || 1));
        // Interval depends on how fast the market absorbs the visible amount (simulated)
        avgIntervalMins = Math.max(1, Math.floor(totalDurationMins / numTranches));
    } 
    else if (algoStrategy === 'VWAP') {
        strategyLabel = 'Volume Weighted';
        alphaSource = 'Liquidity Capture';
        // VWAP splits into finer buckets to match the volume curve
        // Standard bucket size ~5 mins
        numTranches = Math.max(1, Math.floor(totalDurationMins / 5));
        avgIntervalMins = 5;
    } 
    else { // TWAP
        strategyLabel = 'Time Weighted';
        alphaSource = 'Volatility Dampening';
        // TWAP seeks Optimal Clip Size (approx $10k - $50k USD per clip to minimize impact)
        const OPTIMAL_CLIP_USD = 25_000;
        const idealTranches = Math.ceil(grossValue / OPTIMAL_CLIP_USD);

        // Constraints: Min 1 min interval, Max 30 min interval
        const maxTranches = totalDurationMins; 
        const minTranches = Math.ceil(totalDurationMins / 30);

        numTranches = Math.max(minTranches, Math.min(idealTranches, maxTranches));
        avgIntervalMins = Math.floor(totalDurationMins / numTranches);
    }

    // Safety Clamp
    if (numTranches < 1) numTranches = 1;
    if (pay <= 0) numTranches = 0;

    // 3. Impact & Cost Calculation

    // A. Instant Swap Impact (Square Root Law: Impact ~ k * sqrt(Size))
    // Simplified: Impact% = (Size / Depth)^0.8 * Scaling
    const instantImpactPct = Math.pow(grossValue / LIQUIDITY_DEPTH_USD, VOLATILITY_FACTOR) * 2.5; 
    const instantImpactCost = grossValue * (instantImpactPct / 100);

    // B. Algo Impact (Sequential Clips)
    // The market "heals" (mean reverts) between tranches.
    // Theoretical impact of N tranches is 1/sqrt(N) of instant, plus alpha decay.
    const avgClipUSD = grossValue / (numTranches || 1);
    const singleClipImpactPct = Math.pow(avgClipUSD / LIQUIDITY_DEPTH_USD, VOLATILITY_FACTOR) * 2.5;

    // Decay Factor: How much the price recovers between trades (0.0 = full recovery, 1.0 = permanent)
    // Longer intervals = better recovery.
    const recoveryRate = Math.min(0.9, avgIntervalMins * 0.1); 
    const permanentImpactFactor = 1 - recoveryRate;

    // Accumulated slippage cost over the whole order
    const algoImpactCost = grossValue * (singleClipImpactPct / 100) * (1 + (numTranches * permanentImpactFactor * 0.1));

    // C. Hard Costs
    const algoTotalGas = numTranches * GAS_PER_TX_USD;
    const platformFee = grossValue * (PLATFORM_BPS / 10000);
    const totalAlgoCost = algoTotalGas + platformFee + algoImpactCost;

    // D. Net Savings
    // Savings = (Instant Cost) - (Algo Cost including Gas/Fees)
    const netSavings = Math.max(0, instantImpactCost - totalAlgoCost);

    // 4. Schedule Generation (Visualization)
    const scheduleData = [];
    if(numTranches > 0) {
        let currentTime = new Date();
        const displayCount = Math.min(numTranches, 40); // Cap bars for UI
        const step = Math.max(1, Math.floor(numTranches / displayCount));

        for(let i=0; i<displayCount; i++) {
            let volumePct = 100 / displayCount;

            // VWAP Curve Generation (Bell Curve approx)
            if (algoStrategy === 'VWAP') {
                const x = (i / displayCount) * 2 - 1; // -1 to 1
                const bell = Math.exp(-2 * x * x); // Gaussian
                volumePct *= bell; // Scale by bell curve
            }
            // TWAP is flat

            // Randomized noise
            if (algoRandomize) {
                const noise = (Math.random() - 0.5) * 0.4; // +/- 20%
                volumePct *= (1 + noise);
            }

            scheduleData.push({
                id: i,
                time: currentTime.toLocaleTimeString('en-US', {hour:'2-digit', minute:'2-digit', hour12:false}),
                volume: volumePct,
                status: i < 2 ? 'executed' : i === 2 ? 'active' : 'pending'
            });
            currentTime = new Date(currentTime.getTime() + (avgIntervalMins * step * 60000));
        }
    }

    return {
        strategyLabel,
        alphaSource,
        numTranches,
        avgIntervalMins,
        algoTotalGas,
        platformFee,
        totalAlgoCost,
        netSavings,
        scheduleData,
        instantImpactCost,
        grossValue,
    };
  }, [numericPay, algoStrategy, algoDuration, icebergVisibleAmount, algoRandomize]);


  return (
    <>
      <section className="lg:col-span-4 flex flex-col h-full gap-5">

         {/* RUNNING STATE OVERLAY */}
         {isAlgoRunning ? (
             <div className="glass-panel p-2 h-full flex flex-col">
                <div className="bg-[#0a0a0a] rounded-[2.2rem] p-6 border border-white/5 flex flex-col h-full relative overflow-hidden">
                    {/* Background Pulse */}
                    <div className="absolute top-0 right-0 w-full h-full bg-emerald-500/5 animate-pulse pointer-events-none"></div>

                    <div className="flex items-center justify-between mb-8 relative z-10">
                       <span className="text-[10px] font-black text-emerald-500 uppercase tracking-[0.2em] flex items-center gap-2 border border-emerald-500/20 bg-emerald-500/10 px-3 py-1.5 rounded-lg">
                         <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
                         Engine Active
                       </span>
                       <span className="text-[10px] font-mono font-bold text-zinc-400 tabular-nums">{algoStrategy} • {simulation.numTranches} Tranches</span>
                    </div>

                    <div className="flex-1 flex flex-col justify-center relative z-10 space-y-8">
                        <div className="text-center">
                           <p className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest mb-2">Filled Amount</p>
                           <p className="text-5xl font-mono font-medium text-white tabular-nums tracking-tighter">
                               {formatToken((parseFloat(amount) || 0) * (executionProgress/100))} <span className="text-zinc-600 text-3xl">ETH</span>
                           </p>
                        </div>

                        <div className="space-y-2">
                            <div className="flex justify-between text-[9px] font-mono text-zinc-500 uppercase tracking-wider">
                                <span>Progress</span>
                                <span>{executionProgress.toFixed(1)}%</span>
                            </div>
                            <div className="h-4 w-full bg-[#050505] rounded-full overflow-hidden border border-white/5 p-0.5">
                               <div className="h-full rounded-full bg-gradient-to-r from-emerald-600 to-emerald-400 shadow-[0_0_15px_rgba(16,185,129,0.4)] transition-all duration-300 ease-out" style={{ width: `${executionProgress}%` }}></div>
                            </div>
                            <div className="flex justify-center mt-2">
                                <span className="text-[9px] font-mono text-zinc-400 bg-zinc-900 px-2 py-1 rounded">
                                    Est. Time Remaining: <span className="text-white">{Math.ceil(simulation.avgIntervalMins * (simulation.numTranches * (1 - executionProgress/100)))}m</span>
                                </span>
                            </div>
                        </div>
                    </div>

                    <button 
                      onClick={() => setIsAlgoRunning(false)}
                      className="mt-auto w-full py-5 rounded-xl font-black text-[10px] uppercase tracking-[0.2em] bg-rose-500/10 text-rose-500 border border-rose-500/20 hover:bg-rose-500 hover:text-white transition-all flex items-center justify-center gap-3 relative z-10"
                    >
                      <StopCircle size={16} /> Terminate Strategy
                    </button>
                </div>
             </div>
         ) : (
             /* CONFIGURATION STATE */
             <div className="glass-panel p-2">
                <div className="bg-[#0a0a0a] rounded-[2.2rem] p-6 border border-white/5 space-y-2">

                    {/* 1. PAY INPUT BLOCK */}
                    <div className="bg-[#050505] rounded-3xl p-5 border border-white/5 focus-within:border-emerald-500/30 transition-colors group relative">
                        <div className="flex justify-between items-start mb-4">
                            <label className="text-[9px] font-black text-zinc-500 uppercase tracking-[0.2em] group-focus-within:text-emerald-500 transition-colors">Allocated Capital</label>
                            <div className="text-[9px] font-bold text-zinc-500 bg-zinc-900 px-2 py-1 rounded-lg border border-white/5 flex items-center gap-2">
                                <span>Bal: <span className="font-mono text-zinc-300">{formatToken(balance)}</span></span>
                                <button onClick={() => handlePercentageClick(100)} className="text-emerald-500 hover:text-emerald-400 font-black text-[8px] uppercase">Max</button>
                            </div>
                        </div>

                        <div className="flex items-center gap-4">
                            <input 
                                type="text" 
                                value={amount}
                                onChange={(e) => onAmountChange(e.target.value)}
                                className="w-full bg-transparent text-4xl lg:text-5xl font-mono font-medium tracking-tighter text-white placeholder:text-zinc-800 focus:outline-none" 
                                placeholder="0.00" 
                            />
                            <div className="flex items-center gap-2 bg-zinc-900 border border-white/10 pl-2 pr-3 py-2 rounded-xl shrink-0">
                                <div className="w-6 h-6 rounded-full bg-black border border-white/10 flex items-center justify-center p-0.5">
                                    <img src={ETH_ICON} className="w-full h-full object-contain" alt="ETH" />
                                </div>
                                <span className="font-bold text-white text-sm">ETH</span>
                            </div>
                        </div>

                        {/* Footer: USD Value & Percentages (NEW UNIFIED STYLE) */}
                        <div className="flex justify-between items-center mt-3">
                            <div className="text-xs font-mono font-bold text-zinc-600">
                                ≈ {amount ? formatMoney(simulation.grossValue) : '$0.00'}
                            </div>
                            <div className="flex gap-1">
                                {[25, 50, 75, 100].map(pct => (
                                    <button 
                                        key={pct} 
                                        onClick={() => handlePercentageClick(pct)} 
                                        className={`text-[9px] font-bold px-2 py-1 rounded border transition-all ${
                                            isPercentageActive(pct)
                                            ? 'bg-zinc-700 text-white border-white/20 shadow-sm' 
                                            : 'text-zinc-600 hover:text-zinc-300 bg-zinc-900/50 border-white/5'
                                        }`}
                                    >
                                        {pct}%
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>

                    {/* CONNECTOR */}
                    <div className="relative h-4 w-full flex items-center justify-center z-10 -my-3">
                        <div className="p-1.5 bg-[#0a0a0a] rounded-full border border-white/10 shadow-xl">
